var e=[{title:`Невідкладні симптоми`,text:`Негайно припиніть вправи, якщо у вас біль чи тиск у грудях, непритомність, сильна задишка без явної причини, раптова слабкість з одного боку, сильний новий головний біль зі змінами з боку нервової системи або швидко розвивається серйозна реакція. Дискомфорт у грудях із потовиділенням, нудотою, запамороченням чи болем, що поширюється на руку чи щелепу, потребує екстрених служб.`},{title:`Інші серйозні тривожні ознаки`,text:`Не тренуйтеся через раптовий сильний біль у суглобі чи спині, виражений набряк після травми, неможливість спертися на ногу, слабкість, що посилюється, чи нове оніміння. Біль у спині разом із втратою контролю над сечовим міхуром чи кишечником або онімінням навколо паху потребує негайної екстреної оцінки.`},{title:`Що робити`,text:`Зупиніться, убезпечте місце і зверніться по допомогу. Телефонуйте за місцевим номером екстреної допомоги за невідкладних симптомів і не сідайте за кермо самі, якщо можете бути серйозно хворим чи травмованим. Якщо ви партнер по тренуванню, не намагайтеся з’ясувати причину і не підбадьорюйте людину завершити підхід. TrainUp не може оцінити невідкладний стан, діагностувати хворобу чи замінити кваліфікованого фахівця.`},{title:`У профілактики є межі`,text:`Розминка, розумні навантаження та поступова прогресія можуть зменшити стрес, якого можна уникнути, але не можуть виключити кожну медичну проблему. Якщо у вас відома хвороба серця чи великі фактори ризику, перед початком інтенсивних вправ вам може знадобитися особиста порада лікаря.`}];var l=[{label:`NHS: біль у грудях і невідкладні симптоми`,url:`https://www.nhs.uk/symptoms/chest-pain/`},{label:`NHS: біль у спині та термінові тривожні ознаки`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`NHS: біль у суглобах`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var i={sections:e,sources:l};export{i as default,e as sections,l as sources};